// Per-instance TLS material for LND. LND's autogenerated cert is
// self-signed with CA:TRUE — Go and OpenSSL tolerate that shape, but
// strict stacks (rustls/webpki) reject a CA cert in the leaf position.
// We provision a small CA plus a CA:FALSE leaf instead, so every client
// pins the CA and standard chain validation applies.

use std::net::IpAddr;
use std::str::FromStr as _;

use rcgen::{
    BasicConstraints, CertificateParams, DnType, ExtendedKeyUsagePurpose, Ia5String, IsCa, KeyPair,
    KeyUsagePurpose, SanType,
};

/// PEM material for one LND instance.
pub struct InstanceTls {
    /// CA certificate. The bundle carries it; clients pin it as a root.
    pub ca_pem: String,
    /// Leaf + CA chain: the file LND serves.
    pub chain_pem: String,
    /// Leaf private key (PKCS8): the file LND serves with.
    pub key_pem: String,
}

/// Names one instance's leaf must answer to: in-cluster DNS, loopback,
/// and the deployment's public host — the host every bundle URL uses.
fn subject_alt_names(
    instance: &str,
    namespace: &str,
    public_host: &str,
) -> Result<Vec<SanType>, rcgen::Error> {
    let dns = |name: &str| -> Result<SanType, rcgen::Error> {
        Ok(SanType::DnsName(Ia5String::try_from(name.to_string())?))
    };
    let mut sans = vec![
        dns("localhost")?,
        SanType::IpAddress(IpAddr::from([127, 0, 0, 1])),
        dns(&format!("lnd-{instance}"))?,
        dns(&format!("lnd-{instance}.{namespace}.svc"))?,
        dns(&format!("lnd-{instance}.{namespace}.svc.cluster.local"))?,
        dns(&format!(
            "lnd-{instance}-0.lnd-{instance}.{namespace}.svc.cluster.local"
        ))?,
    ];
    if let Ok(ip) = IpAddr::from_str(public_host) {
        sans.push(SanType::IpAddress(ip));
    } else if !public_host.is_empty() {
        sans.push(dns(public_host)?);
    }
    Ok(sans)
}

fn ca_params() -> Result<CertificateParams, rcgen::Error> {
    let mut params = CertificateParams::new(vec![])?;
    params
        .distinguished_name
        .push(DnType::CommonName, "signet lnd ca");
    // Constrained(0): the instance CA signs leaves, nothing else.
    params.is_ca = IsCa::Ca(BasicConstraints::Constrained(0));
    params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];
    Ok(params)
}

fn leaf_params(instance: &str, sans: Vec<SanType>) -> Result<CertificateParams, rcgen::Error> {
    let mut params = CertificateParams::new(vec![])?;
    params
        .distinguished_name
        .push(DnType::CommonName, format!("lnd-{instance}"));
    params.subject_alt_names = sans;
    params.is_ca = IsCa::ExplicitNoCa;
    params.key_usages = vec![
        KeyUsagePurpose::DigitalSignature,
        KeyUsagePurpose::KeyEncipherment,
    ];
    params.extended_key_usages = vec![
        ExtendedKeyUsagePurpose::ServerAuth,
        ExtendedKeyUsagePurpose::ClientAuth,
    ];
    Ok(params)
}

/// rcgen's default validity window spans 1975-4096; sandbox
/// environments are disposable, so there is no rotation machinery.
pub fn generate_instance_tls(
    instance: &str,
    namespace: &str,
    public_host: &str,
) -> Result<InstanceTls, rcgen::Error> {
    let sans = subject_alt_names(instance, namespace, public_host)?;
    let ca_key = KeyPair::generate()?;
    let ca = ca_params()?.self_signed(&ca_key)?;
    let leaf_key = KeyPair::generate()?;
    let leaf = leaf_params(instance, sans)?.signed_by(&leaf_key, &ca, &ca_key)?;
    Ok(InstanceTls {
        ca_pem: ca.pem(),
        chain_pem: format!("{}{}", leaf.pem(), ca.pem()),
        key_pem: leaf_key.serialize_pem(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dns(name: &str) -> SanType {
        SanType::DnsName(Ia5String::try_from(name.to_string()).unwrap())
    }

    #[test]
    fn the_ca_is_a_constrained_ca() {
        let params = ca_params().unwrap();
        assert!(matches!(
            params.is_ca,
            IsCa::Ca(BasicConstraints::Constrained(0))
        ));
    }

    #[test]
    fn the_leaf_is_not_a_ca_and_serves_both_roles() {
        let params = leaf_params("ln-alice", vec![]).unwrap();
        assert!(matches!(params.is_ca, IsCa::ExplicitNoCa));
        assert!(
            params
                .extended_key_usages
                .contains(&ExtendedKeyUsagePurpose::ServerAuth)
        );
        assert!(
            params
                .extended_key_usages
                .contains(&ExtendedKeyUsagePurpose::ClientAuth)
        );
    }

    #[test]
    fn the_public_host_lands_in_the_sans_as_ip_or_dns() {
        let sans = subject_alt_names("ln-alice", "env-x", "192.168.100.2").unwrap();
        assert!(sans.contains(&SanType::IpAddress(IpAddr::from([192, 168, 100, 2]))));

        let sans = subject_alt_names("ln-alice", "env-x", "ln.example.com").unwrap();
        assert!(sans.contains(&dns("ln.example.com")));
    }

    #[test]
    fn instance_and_cluster_names_are_always_covered() {
        let sans = subject_alt_names("ln-alice", "env-x", "").unwrap();
        let names: Vec<&str> = sans
            .iter()
            .filter_map(|s| match s {
                SanType::DnsName(name) => Some(name.as_str()),
                _ => None,
            })
            .collect();
        for name in [
            "localhost",
            "lnd-ln-alice",
            "lnd-ln-alice.env-x.svc",
            "lnd-ln-alice.env-x.svc.cluster.local",
            "lnd-ln-alice-0.lnd-ln-alice.env-x.svc.cluster.local",
        ] {
            assert!(names.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn generation_yields_pinable_material() {
        let tls = generate_instance_tls("ln-alice", "env-x", "192.168.100.2").unwrap();
        assert!(tls.ca_pem.starts_with("-----BEGIN CERTIFICATE"));
        assert_eq!(tls.chain_pem.matches("BEGIN CERTIFICATE").count(), 2);
        assert!(tls.key_pem.contains("PRIVATE KEY"));
    }
}
